/* eslint-disable @next/next/no-img-element */
import { withBase } from "@/lib/site";

type PhotoSpec = { name: string; sizes: readonly number[]; alt: string; width: number; height: number };

/** Responsive WebP image from public/images, generated by scripts/build-images.mjs. */
export function Photo({
  photo,
  sizes,
  className,
  priority = false,
}: {
  photo: PhotoSpec;
  sizes: string;
  className?: string;
  priority?: boolean;
}) {
  const largest = photo.sizes[photo.sizes.length - 1];
  return (
    <img
      src={withBase(`/images/${photo.name}-${largest}.webp`)}
      srcSet={photo.sizes.map((w) => `${withBase(`/images/${photo.name}-${w}.webp`)} ${w}w`).join(", ")}
      sizes={sizes}
      alt={photo.alt}
      width={photo.width}
      height={photo.height}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : "auto"}
      decoding="async"
      className={className}
    />
  );
}
